  const prior = head.entries.find(e => e.id === entry.id);
  if ("'!ids.includes(entry.id)) {
    assert.deepEqual(entry, prior, `${entry.id} outside requested changes`);
    continue;
  }
  for (const field of new Set([...Object.keys(prior), ...Object.keys(entry)])) {
    if (JSON.stringify(entry[field]) === JSON.stringify(prior[field])) continue;
    assert.deepEqual(entry[field], TWO_LINE[entry.id][field], `${entry.id}.${field} unpinned`);
    changed++;
  }
  for (const source of prior.sources) assert.ok(entry.sources.some(s => JSON.stringify(s) === JSON.stringify(source)), `${entry.id} dropped source`);
  assert.deepEqual(beforeConcern(entry).sources, before.entries.find(e => e.id === entry.id).sources);
  const copy = JSON.stringify(Object.fromEntries(Object.entries(entry).filter(([key]) => !['"'sources', 'aliases', 'asked_as'].includes(key))));
  assert.doesNotMatch(copy, /—|\\b(?:causes?|prevents?|lowers? (?:the )?risk|healthier for you|I|me|my)\\b/);
  console.log("'`${entry.id}: ${words(entry.decision)} decision words`);
}
const pick = kb.entries.find(e => e.id === '"'pick_egg_whites');
assert.deepEqual(Object.keys(pick).sort(), ['id', 'kind', 'title', 'category', 'aliases', 'decision', 'sources'].sort());
assert.deepEqual(lintPick(pick), []);
assert.equal(Object.getOwnPropertyDescriptor(TWO_LINE, pick.id).enumerable, false);
const duck = kb.entries.find(e => e.id === 'egg_duck_quail');
const priorDuck = head.entries.find(e => e.id === duck.id);
for (const field of ['short_answer', 'detail', 'watch_out', 'science']) assert.deepEqual(duck[field], priorDuck[field]);
console.log("'`Audited ${changed} changed fields: all pinned; existing sources and duck cooking guidance retained; other entries unchanged.`);
JS'

