import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
const kb = JSON.parse(readFileSync('server/kristy_perimeter_kb.json', 'utf8'));
const fixture = JSON.parse(readFileSync('server/test/acceptance/fixtures/kb-pre-readability.json', 'utf8'));
const archived = new Set();
const root = 'docs/sources/concerns';
for (const directory of readdirSync(root, {withFileTypes:true}).filter(e => e.isDirectory())) {
  for (const filename of readdirSync(join(root, directory.name)).filter(f => f.endsWith('.md'))) {
    const match = readFileSync(join(root, directory.name, filename), 'utf8').match(/"'^url:'"\\s*(\\S+)/m);
    if (match) archived.add(match[1]);
  }
}
for (const id of ['label_cage_free', 'label_pasture_raised_feed']) {
  const prior = (fixture.entries ?? fixture).find(e => e.id === id);
  const live = kb.entries.find(e => e.id === id);
  const archivedCount = entry => entry.sources.filter(source => archived.has(typeof source === 'string' ? (source.match(/https?:\\S+/) ?? [])[0] : source.url)).length;
  assert.equal(archivedCount(prior), 0);
  assert.ok(archivedCount(live) >= 1);
  console.log("'`${id}: K11 demands exact equality with ${prior.sources.length} frozen sources containing zero archive URLs; C4 requires at least one archive URL. Live archive count: ${archivedCount(live)}.`);
}
const allowed = ['"'id', 'kind', 'title', 'category', 'aliases', 'decision', 'sources'];
const glossFields = ['tier_note', 'pick_steps', 'instead'];
assert.equal(glossFields.filter(f => allowed.includes(f)).length, 0);
console.log('The section glossary check accepts only tier_note/pick_steps/instead; all three are forbidden by the pick schema.');
JS"
